-- PT106-S3-Q3. Batch 03.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch03$PT106-S3-Q3$batch03$ AND q.stimulus=$batch03$Birds startled by potential predators generally try to take cover in nearby vegetation. Yet many birds that feed at bird feeders placed in suburban gardens are killed when, thus startled, they fly away from the vegetation in the gardens and into the windowpanes of nearby houses.$batch03$ AND q.prompt=$batch03$Which one of the following, if true, most helps to explain the anomalous behavior of the birds that fly into windowpanes?$batch03$ AND q.correct_choice=$batch03$E$batch03$) THEN RAISE EXCEPTION 'Question changed: PT106-S3-Q3'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch03$PT106-S3-Q3$batch03$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT106-S3-Q3'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch03$PT106-S3-Q3$batch03$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch03$Given that$batch03$, $batch03$Startled birds usually fly toward nearby vegetation for cover.$batch03$), (1, $batch03$How can it be that$batch03$, $batch03$Startled birds at suburban feeders fly *away* from the garden's vegetation and into windows?$batch03$), (2, $batch03$Evaluate$batch03$, $batch03$The birds' instinct is to seek vegetation. What if they think they *are* flying toward vegetation? A window that reflects trees and shrubs would look like cover. Then the birds are following their usual instinct, and the glass is the trap.$batch03$), (3, $batch03$Goal$batch03$, $batch03$Find a reason the windows look like a place to hide.$batch03$)) v(position,label,body) WHERE q.qid=$batch03$PT106-S3-Q3$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch03$A$batch03$, $batch03$How likely an attack is near dense versus sparse vegetation does not explain where a startled bird flies.$batch03$), ($batch03$B$batch03$, $batch03$If some feeders are far from houses, birds there have even less reason to hit windows. It does nothing for the birds that do.$batch03$), ($batch03$C$batch03$, $batch03$Bird size is not part of the puzzle. Large and small birds alike hitting windows leaves the behavior unexplained.$batch03$), ($batch03$D$batch03$, $batch03$Being startled by noise rather than predators might change a reaction in general, but it does not explain flying *into windows* rather than into the vegetation.$batch03$), ($batch03$E$batch03$, $batch03$If the windows reflect the surrounding plants, a fleeing bird sees what looks like cover and flies toward it. It is behaving just as the first sentence says birds do.$batch03$)) v(letter,body) WHERE q.qid=$batch03$PT106-S3-Q3$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
